using System;using System.IO;using System.Linq;using System.Collections.Generic;
using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using CatGunner.Recovery;using Newtonsoft.Json.Linq;
public static class InstallPenguinActionsV2
{
 const string Folder="Assets/Recovery/PenguinActionsV2/";
 static string Dir=>Path.GetFullPath(Application.dataPath+"/../../../art/reskin/penguin-expedition/grip-expression-v2");
 static T Save<T>(string n,T value)where T:UnityEngine.Object{var path=Folder+n+".asset";var old=AssetDatabase.LoadAssetAtPath<T>(path);value.name=n;if(old==null){AssetDatabase.CreateAsset(value,path);return value;}EditorUtility.CopySerialized(value,old);UnityEngine.Object.DestroyImmediate(value);EditorUtility.SetDirty(old);AssetDatabase.SaveAssetIfDirty(old);return old;}
 static Sprite Picture(string n,Vector2 pivot){var path=Folder+n+".png";AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.isReadable=true;imp.textureType=TextureImporterType.Default;imp.mipmapEnabled=false;imp.npotScale=TextureImporterNPOTScale.None;imp.maxTextureSize=512;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.wrapMode=TextureWrapMode.Clamp;imp.alphaIsTransparency=true;imp.SaveAndReimport();var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(path);return Save("actions-"+n,Sprite.Create(tex,new Rect(0,0,tex.width,tex.height),pivot,100,0,SpriteMeshType.FullRect));}
 static Sprite Fit(Sprite old,Sprite target){string n="Fit_"+AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(old))+"_"+target.name;int w=Mathf.RoundToInt(old.rect.width),h=Mathf.RoundToInt(old.rect.height);var tex=new Texture2D(w,h,TextureFormat.RGBA32,false){filterMode=FilterMode.Bilinear,wrapMode=TextureWrapMode.Clamp};var pix=new Color[w*h];float scale=Mathf.Min((float)w/target.texture.width,(float)h/target.texture.height),tw=target.texture.width*scale,th=target.texture.height*scale;for(int y=0;y<h;y++)for(int x=0;x<w;x++){float u=(x-(w-tw)*.5f)/tw,v=(y-(h-th)*.5f)/th;if(u>=0&&u<=1&&v>=0&&v<=1)pix[y*w+x]=target.texture.GetPixelBilinear(u,v);}tex.SetPixels(pix);tex.Apply();tex=Save(n+"Texture",tex);return Save(n,Sprite.Create(tex,new Rect(0,0,w,h),old.pivot/old.rect.size,w/old.bounds.size.x,0,SpriteMeshType.FullRect,old.border));}
 static Vector4 V(JToken j)=>new Vector4((float)j[0],(float)j[1],(float)j[2],(float)j[3]);
 public static string Run(){if(Application.dataPath!="/Volumes/ZHITAI_1T/IdleCatGunner/reconstruction/CatGunnerUnityClient/Assets"||EditorApplication.isPlaying||EditorApplication.isCompiling)throw new Exception("Correct idle EditMode required");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.path!="Assets/Recovery/Scenes/RecoveredClient.unity"||scene.isDirty)throw new Exception("Saved normal scene required");AssetDatabase.Refresh();var c=UnityEngine.Object.FindAnyObjectByType<RecoveryForestClient>(FindObjectsInactive.Include);var full=c.GetComponent<PenguinFullReskin>();Directory.CreateDirectory(Dir+"/backup");if(!File.Exists(Dir+"/backup/RecoveredClient.unity.before"))File.Copy(scene.path,Dir+"/backup/RecoveredClient.unity.before");if(!File.Exists(Dir+"/backup/catalogue.before.json"))File.WriteAllText(Dir+"/backup/catalogue.before.json",EditorJsonUtility.ToJson(full,true));var next=Enumerable.Range(0,25).Select(i=>Picture("skins-"+i.ToString("00"),Vector2.one*.5f)).ToArray();var mappings=full.Sources.Select((s,i)=>new{s,t=full.Replacements[i]}).ToDictionary(p=>p.s,p=>p.t);var old=full.Skins.ToArray();var inv=JObject.Parse(File.ReadAllText(Path.GetFullPath(Application.dataPath+"/../../../art/reskin/penguin-expedition/full-reskin/inventory.json")));var entry=inv["fields"].First(f=>(string)f["type"]=="Skin_manager"&&(string)f["field"]=="Skin_sprites");var originals=entry["sprites"].Select(s=>AssetDatabase.LoadAssetAtPath<Sprite>((string)s["asset"])).ToArray();if(originals.Length!=25)throw new Exception("Skin IDs mismatch");for(int i=0;i<25;i++){foreach(var key in mappings.Keys.ToArray())if(mappings[key]==old[i]||mappings[key].name.EndsWith("_"+old[i].name,StringComparison.Ordinal))mappings[key]=Fit(key,next[i]);mappings[originals[i]]=Fit(originals[i],next[i]);}full.Skins=next;full.PreserveOriginalAttackEffects=true;full.PreserveOriginalRingStyle=true;var data=JArray.Parse(File.ReadAllText(Dir+"/assets.json"));full.EyeA=data.Select(r=>V(r["eyes"][0])).ToArray();full.EyeB=data.Select(r=>V(r["eyes"][1])).ToArray();full.Mouth=data.Select(r=>V(r["mouth"])).ToArray();full.Sources=mappings.Keys.ToArray();full.Replacements=full.Sources.Select(s=>mappings[s]).ToArray();var actions=c.GetComponent<PenguinActionAssets>();if(actions==null)actions=c.gameObject.AddComponent<PenguinActionAssets>();actions.HoldingFlipper=Picture("holding-flipper",new Vector2(.18f,.78f));EditorUtility.SetDirty(actions);EditorUtility.SetDirty(full);EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Scene save failed");File.WriteAllText(Dir+"/installed.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{skins=25,flipper=AssetDatabase.GetAssetPath(actions.HoldingFlipper),bindings=full.Sources.Length,body=AssetDatabase.GetAssetPath(next[0]),scene=scene.path,ice=AssetDatabase.GetAssetPath(c.GetComponent<PenguinExpeditionTheme>().Ice[0]),mapPreserved=true},Newtonsoft.Json.Formatting.Indented));return "Installed 25 body layers, face regions and short independent holding wing; existing map and approved ice retained.";}
}
